def hydrate_time(nanoseconds, tz=None):
    """
    Creates a :class:`Time` or :class:`LocalTime` object from a nanosecond resolution timestamp.

    :param nanoseconds: A nanosecond timestamp
    :type nanoseconds: int
    :param tz: The timezone to set the time in, if the input nanoseconds are in UTC. Defaults to ``None``.
    :type tz: str or :class:`pytz.timezone`
    :return: A :class:`Time` or :class:`LocalTime` object
    """

    if isinstance(nanoseconds, datetime.datetime):
        if tz is not None:
            nanoseconds = pytz.utc.localize(nanoseconds).astimezone(tz)
