    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    class MRUCache(dict):
        """A cache that stores up to `maxsize` most recently accessed keys."""
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.queue = collections.deque()

        def __getitem__(self, key, *args, **kwargs):
            value = super().__getitem__(key, *args, **kwargs)
            self.queue.remove(key)
            self.queue.append(key)
            return value

        def __setitem__(self, key, value, *args, **kwargs):
            if len(self.queue) >= self.maxsize:
                last_key = self.queue.popleft()
                super().__delitem__(last_key)
            super().__setitem__(key, value, *args, **kwargs)
            self.queue.append(key)

        def __delitem__(self, key, *args, **kwargs):
            super().__delitem__(key, *args, **kwargs)
            self.queue.remove(key)

        def __contains__(self, key, *args, **kwargs):
            return super().__contains__(key, *args, **kwargs)

        def __iter__(self):
            return iter(self.queue)

        def __len__(self):
            return len(self.queue)

    def decorator(func):
        cache = MRUCache(maxsize, typed)

        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            value = func(*args, **kwargs)
            cache[key] = value
            return value
        return wrapped
    return decorator

