def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    >>> minimalBases([object, object])
    [object]
    >>> minimalBases([object, object, int, object])
    [object, int]
    """
    seen = set()
    for cls in classes:
        bases = cls.__bases__
        while bases:
            new_bases = list()
            for base in bases:
                if base not in seen:
                    seen.add(base)
                    new_bases.append(base)
            bases = new_bases
    return list(seen)

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    """
    seen = set()
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        yield cls
        for b in minimalBases(cls.__bases__):
            yield b

