def is_fill_request_seq(seq):
    """
    Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if seq is None:
        return False

    # If it is a Source sequence, immediately return False
    if isinstance(seq, Source):
        return False

    # If it is a FillRequest element, return True immediately
    if isinstance(seq, FillRequest):
        return True

    # If it is a list, check if it contains at least one FillRequest element
    if isinstance(seq, list):
        for item in seq:
            if is_fill_request_seq(item):
                return True
        return False

    # If it is a tuple, check if it contains at least one FillRequest element
    if isinstance(seq, tuple):
        for item in seq:
            if is_fill_request_seq(item):
                return True
        return False

    # If it is a FillRequestSeq, return True immediately
    if isinstance(seq, FillRequestSeq):
        return True

    # If it is any other type of sequence, return False
    if isinstance(seq, pydoc.Sequence):
        return False

    # If the type is unknown, return False
    return False

def is_fill_request_seq(seq):
