def _validate_labels(labels):
    """Validate the given labels by checking if the keys and values match their corresponding regular expressions.

    Raises:
        ValidationError: If any of the keys and values in the labels do not match their respective regular expressions. The error message contains a list of all the errors which occurred in the labels. Each element of the list is a dictionary with one key-value pair:
                - key: the key or value of the label that caused the error.
                - value: the error message.

                .. code:: python

                    # Example:
                    labels = {
                        "key1": "valid",
                        "key2": ["invalid"],
                        "$$": "invalid",
                        True: True,
                    }
                    try:
                        _validate_labels(labels)
                    except ValidationError as err:
                        assert err.messages == [
                            {"['invalid']": 'expected string or bytes-like object'},
                            {'$$': "Label key '$$' does not match the regex [...]"},
                            {'True': 'expected string or bytes-like object'},
                            {'True': 'expected string or bytes-like object'},
                        ]
    """
    errors = []
    for label_key, label_value in labels.items():
        if not regex.match(LABEL_KEY_RE, label_key)
            errors.append({f"{label_key}": "Label key '{label_key}' does not match the regex {LABEL_KEY_RE.pattern}")})
        elif not regex.match(LABEL_VALUE_RE, label_value):
            errors.append({f"{label_value}": f"Label value '{label_value}' does not match the regex {LABEL_VALUE_RE.pattern}"})
    if errors:
        raise ValidationError(", ".join([f"{error['label']}: {error['message']}" for error in errors]))
    return True

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective regular expression. The error contains as message the list of all errors which occurred in the labels. Each element of the list is a dictionary with one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    messages = []
    for label, value in labels.items():
        if not isinstance(label, str):
            messages.append({str(label): 'expected string or bytes-like object'})
        if not isinstance(value, str):
            messages.append({str(value): 'expected string or bytes-like object'})
        if re.match(LABEL_KEY_REGEX, label) is None:
            messages.append({label: f"Label key '{label}' does not match the regex {LABEL_KEY_REGEX.pattern}"})
        if re.match(LABEL_VALUE_REGEX, value) is None:
            messages.append({value: f"Label value '{value}' does not match the regex {LABEL_VALUE_REGEX.pattern}"})
    if messages:
        raise ValidationError(messages)

