def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with generate_default_observer_schema_list, this function is called
    recursively to generate part of a default observer_schema from part of a
    Kubernetes resource, defined respectively by manifest_dict or manifest_list.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer_schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from manifest_dict and replaces all
    non-list and non-dict values by None.

    In case of first_level dictionary (i.e. complete observer_schema for a
    resource), the values of the identifying fields are copied from the manifest
    file.
    """

    new = {}

    if first_level:
        for k, v in manifest_dict.items():
            if isinstance(v, (list, tuple)):
                new_v = []
                for item in v:
                    if isinstance(item, dict):
                        new_v.append(generate_default_observer_schema_dict(item, first_level=first_level))
                    else:
                        new_v.append(item)
                v = new_v
            new[k] = v
    else:
        for k, v in manifest_dict.items():
            if isinstance(v, (list, tuple)):
                new_v = []
                for item in v:
                    if isinstance(item, dict):
                        new_v.append(generate_default_observer_schema_dict(item, first_level=first_level))
                    else:
                        new_v.append(None)
                v = new_v
            new[k] = v

    return new

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate part of a default ``observer_schema`` from part of a Kubernetes resource.
    """
    new_dict = {}
    for key, value in manifest_dict.items():
        if not isinstance(value, dict) and not isinstance(value, list):
            new_dict[key] = None
        else:
            new_dict[key] = generate_default_observer_schema_dict(value, first_level=first_level)

    if first_level:
        new_dict["apiVersion"] = manifest_dict.get("apiVersion")
        new_dict["kind"] = manifest_dict.get("kind")
        new_dict["metadata"] = manifest_dict.get("metadata", {})

    return new_dict

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Updates a partial `last_applied_manifest` list from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): The partial `last_applied_manifest` being updated.
        observer_schema (list): The partial `observer_schema`.
        response (list): The partial response from the Kubernetes API.
    """
    # Go through all observed fields in the schema and initialize their value in the last_applied_manifest if they are not yet present
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest.append(field)
    for i, response_field in enumerate(response):
        if i < len(last_applied_manifest):
            # If the current field in the response is the same as in the last_applied_manifest, then update its value
            if response_field == last_applied_manifest[i]:
                last_applied_manifest[i] = response_field
        else:
            # If the current field in the response is not in the last_applied_manifest, then add it to the end of the list
            last_applied_manifest.append(response_field)
    return last_applied_manifest

