def generate_default_observer_schema(app):
    """
    :param app: The application for which to generate a default observer schema
    """
    from krake.data.kubernetes import Application
    from pydantic import Field
    from krake.data.kubernetes.observer import ObserverSchema

    app = Application(app)

    observer_schemas = {}

    # Generate default observer schema for each resource
    for resource in app.spec.manifest:
        if isinstance(resource, dict):
            resource_type = resource["kind"].lower()
            if resource_type not in observer_schemas:
                if resource_type in ObserverSchema.__annotations__:
                    observer_schemas[resource_type] = ObserverSchema(**{
                        "type": "dict",
                        "schema": ObserverSchema.__annotations__[resource_type]
                    })
                    print(f"Generated default observer schema for {resource_type} resource")
                else:
                    print(f"No default observer schema specified for {resource_type} resource")

    return observer_schemas

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    schema = deepcopy(app.spec.manifest)
    for resource_name, resource in schema.items():
        if 'observer' not in resource:
            resource['observer'] = {
                'name': f'default-observer-{resource_name.replace("_", "-")}',
                'settings': {},
            }
    return schema

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in ``spec.manifest`` for which a custom observer schema hasn't been specified.

    :param app: The application for which to generate a default observer schema
    """
    # Iterate over each resource in the manifest
    for resource in app.spec.manifest:
        # Check if a custom observer schema has been specified for the resource
        if resource.observer_schema is None:
            # If not, create a new observer schema based on the resource's defaults
            resource.observer_schema = generate_observer_schema(resource.defaults)


def generate_observer_schema(defaults):
    """
    Generate an observer schema for a given resource based on its defaults.

    :param defaults: The defaults for the resource
    :return: An observer schema for the resource
    """
    schema = {}

    # Iterate over each field in the resource's defaults
    for field, value in defaults.items():
        # Check if a custom schema definition has been specified for the field
        if "schema" in value:
            # If so, use the specified schema definition
            schema[field] = value["schema"]
        else:
            # Otherwise, generate a schema definition based on the field's default value
            schema[field] = {"type": type(value).__name__, "nullable": True}

