        return data

def _explore_folder(folder):
    files = os.listdir(folder)
    packages = {}

    for file in files:
        file_name = os.path.splitext(file)[0]

        if file_name not in packages:
            packages[file_name] = {}

        file_path = os.path.join(folder, file)
        with open(file_path, 'r') as f:
            content = f.read()

        if 'Tweag.HEAP.EDom.Types' in content:
            packages[file_name]['EDom.Types'] = content
        elif 'Tweag.HEAP.EDom.Types.EDom' in content:
            packages[file_name]['EDom.Types.EDom'] = content
        elif 'Tweag.HEAP.EDom.Types.EDom.Types' in content:
            packages[file_name]['EDom.Types.Types'] = content
        elif 'Tweag.HEAP.Request.Types' in content:
            packages[file_name]['Request.Types'] = content
        elif 'Tweag.HEAP.Request' in content:
            packages[file_name]['Request'] = content
        elif 'Tweag.HEAP.Response.Types' in content:
            packages[file_name]['Response.Types'] = content
        elif 'Tweag.HEAP.Response' in content:
            packages[file_name]['Response'] = content
        elif 'Tweag.HEAP.Types' in content:
