def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """

    # Extrai o valor da digit strings
    number_raw = issue[0]
    suppl_raw = None
    if len(number_raw) == 1 and number_raw.isdigit():
        number = int(number_raw)
        suppl = None
    elif number_raw[0] == "(" and number_raw[-1] == ")":
        number_raw = number_raw[1:-1].strip()
        suppl_raw = number_raw.split(" ")
        number = int(suppl_raw[0])
        if len(suppl_raw) > 1:
            suppl = " ".join(suppl_raw[1:]).strip()
        else:
            suppl = None
    else:
        return (None, None)

    # Extrai a informação do suplemento
    if suppl_raw is None and suppl is not None:
        if suppl.startswith("Suppl"):
            suppl_raw = suppl
            suppl = None

    if suppl_raw is not None:
        suppl = suppl_raw.strip()

    return (number, suppl)

