def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    new_args = []
    for arg in args:
        if isinstance(arg, str):
            new_args.append(arg)
        else:
            if arg.startswith("&"):
                new_args.append(arg[0].replace("&", "") + "(" + arg[1:] + ")")
            elif arg == "|":
                new_args.append(arg)
            elif arg == "~":
                new_args.append(arg[0].replace("~", "") + "(" + arg[1:] + ")")
            else:
                raise ValueError("invalid argument: {}".format(arg))

    return new_args

// Encapsulate the logic for absorption and negative absorption in two separate functions
def absorb_impl(left, right, is_absorbed=True):
    # Logic for absorption
    if is_absorbed:
        # If left and right both match, return left as the result
        if left == right:
            return left
        # If only left matches, return left
        elif left == '*' or right == '*':
            return left
        # Otherwise, return '*'
        else:
            return '*'
    else:
        # If left and right both match, return right as the result
        if left == right:
            return right
        # If only left matches, return right
        elif left == '*' or right == '*':
            return right
        # Otherwise, return '*'
        else:
            return '*'

def absorb(self, args):
    return self.map(lambda expr: absorb_impl(expr[0], expr[1], is_absorbed=True), args).map(lambda expr: absorb_impl(expr[0], expr[1], is_absorbed=False), args).collect()

