def neg_absorb(self, arg):
    if isinstance(arg, bool):
        return not arg
    elif isinstance(arg, int):
        return -arg
    elif isinstance(arg, str):
        return "-{}".format(arg)
    else:
        raise ValueError("Unsupported type for negation: {}".format(type(arg)))

def absorb_expr(self, expr):
    if isinstance(expr, str):
        return self.absorb(expr)
    elif isinstance(expr, list):
        return self.absorb_expr(expr[0]) & self.neg_absorb_expr(expr[1])
