def render(pieces, style):
    """Render the given version pieces into the requested style."""

    # If the style is "basic", just concatenate the pieces together
    if style == "basic":
        return "".join(pieces)

    # If the style is "styled", we need to use a higher-level format, so we use a piece table
    elif style == "styled":
        # Create a dictionary to store the pieces in
        piece_table = {}

        # Iterate over the pieces
        for i, piece in enumerate(pieces):
            # If the piece is not in the table yet, add it
            if piece not in piece_table:
                piece_table[piece] = i

        # Create a list to store the styled pieces in
        styled_pieces = []

        # Iterate over the pieces in the table
        for piece, i in piece_table.items():
            # If the piece is not the first one, add a newline
            if i != 0:
                styled_pieces.append("\n")

            # Add the piece
            styled_pieces.append(piece)

        # Join the styled pieces together
        return "".join(styled_pieces)

    # If the style is not recognized, raise an error
    else:
        raise ValueError("Style not recognized: %s" % style)

