    """Run the given command(s) using subprocess.run()."""
    try:
        outputs = []
        for command in commands:
            output = None
            try:
                output = subprocess.run(command.split(), args, cwd=cwd, check=True,
                                        capture_output=False, text=True, env=env)
            except subprocess.CalledProcessError:
                msg = f"Command {command} failed with exit code {output.returncode}"
            else:
                outputs.append(output)
            if verbose:
                if hide_stderr:
                    print(output.stdout)
                else:
                    print(output.stdout)
                    print(output.stderr)
            elif hide_stderr:
                print(output.stdout)
            else:
                print(output.stdout)
    except subprocess.CalledProcessError:
        msg = f"couldn't run command\n{command}"
        raise ProgramError(msg)
    return outputs

