    if not os.path.exists(archive_path):
        raise ValueError("Archive does not exist")

    # Define the temporary directory where we will extract the archive
    if not os.path.isdir(tmp_path):
        os.mkdir(tmp_path)

    # Extract the archive to the temporary directory
    subprocess.run(["tar", "-xvf", archive_path, "-C", tmp_path])

    # Find the file with the name of the repo inside the temporary directory
    repo_file = None
    for root, dirs, files in os.walk(tmp_path, topdown=False):
        for name in files:
            if name == filename:
                repo_file = os.path.join(root, name)

    if repo_file is None:
        raise ValueError("Could not find a file with the desired name in the archive")

    # Return the file url for the repo file
    return repo_file

