def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    try:
        url = urllib.parse.urlparse(image_href)
    except (TypeError, ValueError):
        raise ValueError("Invalid image reference: {}".format(image_href))
    if url.netloc == "imgur.com":
        image_id = url.path.lstrip("/")
        netloc = "imgur.com"
        use_ssl = True
    elif url.scheme in ("http", "https") and url.netloc.endswith("imgur.com"):
        netloc = "imgur.com"
        use_ssl = url.scheme == "https"
        image_id = url.path.lstrip("/")
    else:
        raise ValueError(
            "Invalid image reference: {}".format(image_href)
        )
    if not url.fragment:
        raise ValueError(
            "Image reference must contain an image ID: {}".format(image_href)
        )
    return image_id, netloc, use_ssl

