def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, list):
        raise ValueError("commands must be a string or a list of strings")
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, list):
        raise ValueError("args must be a string or a list of strings")
    if env is not None:
        if not isinstance(env, dict):
            raise ValueError("env must be a dictionary")
    if cwd is not None:
        if not isinstance(cwd, str):
            raise ValueError("cwd must be a string")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a bool")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a bool")
    if len(commands) == 0:
        raise ValueError("commands must not be empty")
    if len(commands) > 1 and len(args) != 0:
        raise ValueError("args are not supported for multiple commands")

    if verbose:
        print("Calling command(s):")
        for i, cmd in enumerate(commands):
            print(f"{i+1}. {cmd} {args}")

    if cwd is not None:
        cwd = os.path.abspath(cwd)

    if env is not None:
        env = env.copy()
    else:
        env = {}

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    if len(commands) == 1:
        cmd = commands[0]
        argv = shlex.split(args)
        proc = subprocess.Popen([cmd] + argv, cwd=cwd, env=env, stderr=stderr)

