    # determine the metaclass for a class based on its bases and explicit __metaclass__
    if explicit_mc:
        # use the explicit __metaclass__ if provided
        metaclass = explicit_mc
    else:
        # find the metaclass in the bases
        for base in bases:
            if isinstance(base, type):
                metaclass = base
