def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """

    # Verify the signature of the <samlp:Response> element
    response_signature = doc.find('./samlp:Response/ds:Signature', NAMESPACES)
    if response_signature is not None:
        try:
            public_key.verify(
                response_signature.find('./ds:SignatureValue', NAMESPACES).text,
                response_signature.find('./ds:SignedInfo', NAMESPACES)
            )
            return True
        except xmlsec.Error:
            return False

    # Verify the signature of the <saml2p:Response> element
    pdp_response_signature = doc.find('./saml2p:Response/ds:Signature', NAMESPACES)
    if pdp_response_signature is not None:
        try:
            public_key.verify(
                pdp_response_signature.find('./ds:SignatureValue', NAMESPACES).text,
                pdp_response_signature.find('./ds:SignedInfo', NAMESPACES)
            )
            return True
        except xmlsec.Error:
            return False

    return False

