def parse_xrd(document: str) -> Dict:
    """
    Parse Diaspora webfinger using XRD format.

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    tree = ElementTree.fromstring(document)
    properties = {}
    for property in tree.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Property", namespaces=XRD_NAMESPACES):
        name = property.get("{" + XRD_NAMESPACES["xri"] + "}alias")
        value = []
        for resource in property.findall("{" + XRD_NAMESPACES["xrd"] + "}Resource", namespaces=XRD_NAMESPACES):
            href = resource.get("{" + XRD_NAMESPACES["xri"] + "}hr")
            din = resource.get("{" + XRD_NAMESPACES["diaspora"] + "}din")
            thumb = resource.get("{" + XRD_NAMESPACES["diaspora"] + "}thumb-micro").lstrip("hmac:base64:")
            media_type = resource.get("{" + XRD_NAMESPACES["diaspora"] + "}media-type")
            value.append({
                "href": href,
                "din": din,
                "thumb": thumb,
                "media-type": media_type,
            })
        properties[name]

