def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param root_subparsers: the subparser object to extend.
    """

    spec_parser = root_subparsers.add_parser('spec', help='Manipulate the spec of a target')
    spec_subparsers = spec_parser.add_subparsers()

    load_subcommands = load_subcommands('jellyfish.cli.spec_cmds')
    load_subcommands(spec_subparsers)

    # handle any additional subcommands added by plugins
    for ext in self.extensions:
        if ext.root_subparser_name == 'spec':
            ext.root_subparser(spec_subparsers)

    spec_parser.set_defaults(handler=self.handle_spec)

def handle_spec(args):
    """
    Handles the spec sub command
    """

    if not hasattr(args, 'spec_root_subparser_name'):
        raise ValueError('Subcommand not defined')
    subcommand_name = args.spec_root_subparser_name

    func = sys.modules['jellyfish.cli.spec_cmds'].__dict__.get(subcommand_name)
    if func is None:
        raise ValueError('Subcommand not found')

    func(args)

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
